export function refFromObservation(text, label) {
  const re = /\[(\d+)\]\s+\S+\s+"([^"]*)"/g
  let m
  while ((m = re.exec(text ?? ''))) {
    if (String(m[2]).includes(label)) return Number(m[1])
  }
  return null
}

