// ── ⑥ 읽기 전용 확인 — 표지 없는 결론은 인정하지 않는다(불확실 유지) ─────────────────
//
// 확인 대상은 **부정 대조 워크플로**다. 이유를 숨기지 않고 적는다: ①에서 크래시로 게시 작업
// 기록 자체가 사라지면(아래 R3 판정 참고) 제품은 그 작업의 세션(워크스페이스)을 알 수 없어
// 확인 작업을 시작하지 않고 "직접 확인해 주세요"로 거절한다 — 그것이 설계상 옳은 보수적 동작이라
// 여기서 우회하지 않는다. 대신 게시 작업이 살아 있는(불확실 상태인) 워크플로로 같은 경로를 검증한다.
if (negDrive.id) {
  control.holdPublish = false          // 확인용 페이지 조회는 정상 응답
  phase.name = 'verify'
  phase.verifyResult = '아마 올라간 것 같기도 합니다(확실하지 않음).'
  const routerV = makeR3Router(phase, routerLog)
  llm.setScript([routerV.step])
  const beforeVerify = pubCount()

  const v1 = await evalIn(app.shell, `window.browserAPI.ai.socialResolvePublish(${J(negDrive.id)}, ${J('verify')})`, true)
  await waitUntil(async () => {
    const wf = await getWorkflow(app.shell, negDrive.id)
    return !!wf && !wf.verifyTaskId
  }, 90000, 800)
  await sleep(1500)
  const wfUnmarked = await getWorkflow(app.shell, negDrive.id)
  const afterUnmarked = pubCount()

  // 표지가 있는 확인 — 확실한 영수증이면 완료로 확정되어야 한다.
  phase.verifyResult = '게시됨: 게시물 목록에서 같은 문구의 글을 확인했습니다.'
  const routerV2 = makeR3Router(phase, routerLog)
  llm.setScript([routerV2.step])
  const v2 = await evalIn(app.shell, `window.browserAPI.ai.socialResolvePublish(${J(negDrive.id)}, ${J('verify')})`, true)
  const doneOk = await waitUntil(async () => {
    const wf = await getWorkflow(app.shell, negDrive.id)
    return !!wf && wf.stage === 'done'
  }, 90000, 800)
  const wfMarked = await getWorkflow(app.shell, negDrive.id)
  const afterMarked = pubCount()

  const triedWrites = routerV.st.vStep >= 2 || routerV2.st.vStep >= 2   // 읽기전용 작업이 type·upload_file 을 실제로 시도했다
  const unmarkedStaysUncertain = wfUnmarked?.publishUncertain === true && wfUnmarked?.stage !== 'done'
  check('R3-RO', '읽기 전용 확인 — 악성 지시대로 쓰기를 시도해도 차단 · 표지 없으면 불확실 유지 · 표지 있으면 완료 확정(추가 게시 0)',
    !!(triedWrites && unmarkedStaysUncertain && doneOk && afterMarked === beforeVerify && afterUnmarked === beforeVerify),
    `확인 중 서버 게시: ${beforeVerify} → 표지없음 후 ${afterUnmarked} → 표지있음 후 ${afterMarked}(추가 ${afterMarked - beforeVerify}건) `
    + `· 읽기전용 작업이 type·upload_file 을 시도함=${triedWrites} `
    + `· 표지없음 결과: stage=${wfUnmarked?.stage} publishUncertain=${wfUnmarked?.publishUncertain} nextAction="${(wfUnmarked?.recovery?.nextAction ?? '').slice(0, 60)}" `
    + `· 표지있음 결과: stage=${wfMarked?.stage} receipt="${(wfMarked?.receipt?.evidence ?? '').slice(0, 70)}" `
    + `· resolve 응답 ${J(v1)} / ${J(v2)}`)
} else {
  skip('R3-RO', '읽기 전용 확인', '부정 대조 워크플로가 만들어지지 않아 확인 경로를 시험할 대상이 없음')
}

